import{_ as t,o as d,c as e,Q as i}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"数字与数词语法","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/grammar/05-numbers.md","filePath":"zh/more/maltese/grammar/05-numbers.md"}'),r={name:"zh/more/maltese/grammar/05-numbers.md"},a=i('<h1 id="数字与数词语法" tabindex="-1">数字与数词语法 <a class="header-anchor" href="#数字与数词语法" aria-label="Permalink to &quot;数字与数词语法&quot;">​</a></h1><h2 id="_1-0-到-20" tabindex="-1">1. 0 到 20 <a class="header-anchor" href="#_1-0-到-20" aria-label="Permalink to &quot;1. 0 到 20&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">数字</th><th>English</th><th>Malti</th><th>中文</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>zero</td><td>żero</td><td>零</td></tr><tr><td style="text-align:right;">1</td><td>one</td><td>wieħed / waħda</td><td>一（阳性/阴性形式）</td></tr><tr><td style="text-align:right;">2</td><td>two</td><td>tnejn</td><td>二</td></tr><tr><td style="text-align:right;">3</td><td>three</td><td>tlieta</td><td>三</td></tr><tr><td style="text-align:right;">4</td><td>four</td><td>erbgħa</td><td>四</td></tr><tr><td style="text-align:right;">5</td><td>five</td><td>ħamsa</td><td>五</td></tr><tr><td style="text-align:right;">6</td><td>six</td><td>sitta</td><td>六</td></tr><tr><td style="text-align:right;">7</td><td>seven</td><td>sebgħa</td><td>七</td></tr><tr><td style="text-align:right;">8</td><td>eight</td><td>tmienja</td><td>八</td></tr><tr><td style="text-align:right;">9</td><td>nine</td><td>disgħa</td><td>九</td></tr><tr><td style="text-align:right;">10</td><td>ten</td><td>għaxra</td><td>十</td></tr><tr><td style="text-align:right;">11</td><td>eleven</td><td>ħdax</td><td>十一</td></tr><tr><td style="text-align:right;">12</td><td>twelve</td><td>tnax</td><td>十二</td></tr><tr><td style="text-align:right;">13</td><td>thirteen</td><td>tlettax</td><td>十三</td></tr><tr><td style="text-align:right;">14</td><td>fourteen</td><td>erbatax</td><td>十四</td></tr><tr><td style="text-align:right;">15</td><td>fifteen</td><td>ħmistax</td><td>十五</td></tr><tr><td style="text-align:right;">16</td><td>sixteen</td><td>sittax</td><td>十六</td></tr><tr><td style="text-align:right;">17</td><td>seventeen</td><td>sbatax</td><td>十七</td></tr><tr><td style="text-align:right;">18</td><td>eighteen</td><td>tmintax</td><td>十八</td></tr><tr><td style="text-align:right;">19</td><td>nineteen</td><td>dsatax</td><td>十九</td></tr><tr><td style="text-align:right;">20</td><td>twenty</td><td>għoxrin</td><td>二十</td></tr></tbody></table><h2 id="_2-整十与大数" tabindex="-1">2. 整十与大数 <a class="header-anchor" href="#_2-整十与大数" aria-label="Permalink to &quot;2. 整十与大数&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">数字</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">30</td><td>thirty</td><td>tletin</td></tr><tr><td style="text-align:right;">40</td><td>forty</td><td>erbgħin</td></tr><tr><td style="text-align:right;">50</td><td>fifty</td><td>ħamsin</td></tr><tr><td style="text-align:right;">60</td><td>sixty</td><td>sittin</td></tr><tr><td style="text-align:right;">70</td><td>seventy</td><td>sebgħin</td></tr><tr><td style="text-align:right;">80</td><td>eighty</td><td>tmenin</td></tr><tr><td style="text-align:right;">90</td><td>ninety</td><td>disgħin</td></tr><tr><td style="text-align:right;">100（单独报数）</td><td>one hundred (standalone)</td><td>mija</td></tr><tr><td style="text-align:right;">100（名词前）</td><td>one hundred (before a noun)</td><td>mitt</td></tr><tr><td style="text-align:right;">200</td><td>two hundred</td><td>mitejn</td></tr><tr><td style="text-align:right;">1,000</td><td>one thousand</td><td>elf</td></tr><tr><td style="text-align:right;">2,000</td><td>two thousand</td><td>elfejn</td></tr><tr><td style="text-align:right;">1,000,000</td><td>one million</td><td>miljun</td></tr></tbody></table><h2 id="_3-组合数字" tabindex="-1">3. 组合数字 <a class="header-anchor" href="#_3-组合数字" aria-label="Permalink to &quot;3. 组合数字&quot;">​</a></h2><p>常见的“个位 + u + 整十”组合用于 21–99。<code>u</code> 在这里是“和”。例如 <code>ħamsa u għoxrin</code>（25）。整百、整千另有形式，不能把“个位 + u + 整十”的规则机械扩展到全部数值。</p><ul><li>21：<code>wieħed u għoxrin</code></li><li>22：<code>tnejn u għoxrin</code></li><li>35：<code>ħamsa u tletin</code></li><li>48：<code>tmienja u erbgħin</code></li><li>99：<code>disgħa u disgħin</code></li></ul><p>整百和整千常用这些形式：<code>mija</code>（一百，单独报数）、<code>mitt</code>（一百，置于名词前）、<code>mitejn</code>（二百）、<code>tliet mija</code>（三百）、<code>elf</code>（一千）、<code>elfejn</code>（两千）、<code>tlitt elef</code>（三千）。实际搭配中，数词还可能出现短式或长式；日期、时间和计数形式并非总能互换。</p><h2 id="_4-性别与数词形式" tabindex="-1">4. 性别与数词形式 <a class="header-anchor" href="#_4-性别与数词形式" aria-label="Permalink to &quot;4. 性别与数词形式&quot;">​</a></h2><ul><li><code>wieħed</code> 常与阳性名词相关，<code>waħda</code> 常与阴性名词相关。例：<code>raġel wieħed</code>（一个男人）、<code>dar waħda</code>（一所房子）。</li><li>数词在实际搭配中可能出现缩合或特殊形式，例如 <code>żewġt iklieb</code>（两只狗）、<code>żewġt itfal</code>（两个孩子）。不要假设所有数词都只需直接放在名词前。</li><li>2–10 的形式和名词数、性别搭配有历史形态规律，常见说法需要作为词组记忆；本页列的是便于入门的独立数词形式。</li></ul><blockquote><p><strong>Tip</strong>：<code>tlieta</code> 是“三”的独立计数形式，例如 <code>Wieħed, tnejn, tlieta</code>（一、二、三）。名词前用修饰名词的形式：通常用短式 <code>tliet</code>，所以是 <code>tliet sigħat</code>（三小时）、<code>tliet ġimgħat</code>（三周）；<code>jiem</code>（天）是特殊搭配，用 <code>tlett ijiem</code>（三天）。因此不要把独立形式 <code>tlieta</code> 直接放到这些名词前。</p></blockquote><h2 id="_5-序数词" tabindex="-1">5. 序数词 <a class="header-anchor" href="#_5-序数词" aria-label="Permalink to &quot;5. 序数词&quot;">​</a></h2><p>序数词表示“第几”。常见形式通常与定冠词连用，并放在名词前，如 <code>l-ewwel jum</code>（第一天）、<code>it-tieni darba</code>（第二次）。</p><table><thead><tr><th style="text-align:right;">数字</th><th>中文序数</th><th>English ordinal</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>第一</td><td>first</td><td>l-ewwel</td></tr><tr><td style="text-align:right;">2</td><td>第二</td><td>second</td><td>it-tieni</td></tr><tr><td style="text-align:right;">3</td><td>第三</td><td>third</td><td>it-tielet</td></tr><tr><td style="text-align:right;">4</td><td>第四</td><td>fourth</td><td>ir-raba&#39;</td></tr><tr><td style="text-align:right;">5</td><td>第五</td><td>fifth</td><td>il-ħames</td></tr><tr><td style="text-align:right;">6</td><td>第六</td><td>sixth</td><td>is-sitt</td></tr><tr><td style="text-align:right;">7</td><td>第七</td><td>seventh</td><td>is-seba&#39;</td></tr><tr><td style="text-align:right;">8</td><td>第八</td><td>eighth</td><td>it-tmien</td></tr><tr><td style="text-align:right;">9</td><td>第九</td><td>ninth</td><td>id-disa&#39;</td></tr><tr><td style="text-align:right;">10</td><td>第十</td><td>tenth</td><td>l-għaxar</td></tr><tr><td style="text-align:right;">11</td><td>第十一</td><td>eleventh</td><td>il-ħdax</td></tr><tr><td style="text-align:right;">12</td><td>第十二</td><td>twelfth</td><td>it-tnax</td></tr><tr><td style="text-align:right;">13</td><td>第十三</td><td>thirteenth</td><td>it-tlettax</td></tr><tr><td style="text-align:right;">14</td><td>第十四</td><td>fourteenth</td><td>l-erbatax</td></tr><tr><td style="text-align:right;">15</td><td>第十五</td><td>fifteenth</td><td>il-ħmistax</td></tr><tr><td style="text-align:right;">16</td><td>第十六</td><td>sixteenth</td><td>is-sittax</td></tr><tr><td style="text-align:right;">17</td><td>第十七</td><td>seventeenth</td><td>is-sbatax</td></tr><tr><td style="text-align:right;">18</td><td>第十八</td><td>eighteenth</td><td>it-tmintax</td></tr><tr><td style="text-align:right;">19</td><td>第十九</td><td>nineteenth</td><td>id-dsatax</td></tr><tr><td style="text-align:right;">20</td><td>第二十</td><td>twentieth</td><td>l-għoxrin</td></tr></tbody></table><p>上述形式适合入门对照；与名词连用时，通常保留定冠词并作为整体记忆。</p><p>分数和小数在实际应用中要结合数学、货币或测量语境。日常购物时，初学者可以先掌握数字读法，并在不确定时用数字书写或请对方重复。</p><h2 id="_6-价格与数量例句" tabindex="-1">6. 价格与数量例句 <a class="header-anchor" href="#_6-价格与数量例句" aria-label="Permalink to &quot;6. 价格与数量例句&quot;">​</a></h2><ul><li><code>Kemm jiswa dan?</code>：这个多少钱？（指阳性名词）</li><li><code>Kemm tiswa din?</code>：这个多少钱？（指阴性名词）</li><li><code>Żewġ kafejiet, jekk jogħġbok.</code>：请给我两杯咖啡。（<code>kafè</code> 的复数形式会依具体用法变化，此处列出常见复数表达）</li><li><code>Għandi tliet kotba.</code>：我有三本书。</li></ul><blockquote><p>说明：数词与名词的搭配形式不完全规则。正式使用时请把常见搭配作为整体记忆，并用词典确认不熟悉的名词复数。</p></blockquote><h2 id="_7-10-个大数例子" tabindex="-1">7. 10 个大数例子 <a class="header-anchor" href="#_7-10-个大数例子" aria-label="Permalink to &quot;7. 10 个大数例子&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>中文</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>二十五</td><td>twenty-five</td><td>ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">2</td><td>一百二十五</td><td>one hundred and twenty-five</td><td>mija u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">3</td><td>二百二十五</td><td>two hundred and twenty-five</td><td>mitejn u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">4</td><td>三百二十五</td><td>three hundred and twenty-five</td><td>tliet mija u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">5</td><td>一千零二十五</td><td>one thousand and twenty-five</td><td>elf u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">6</td><td>一千一百二十五</td><td>one thousand one hundred and twenty-five</td><td>elf, mija u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">7</td><td>两千一百二十五</td><td>two thousand one hundred and twenty-five</td><td>elfejn, mija u ħamsa u għoxrin</td></tr><tr><td style="text-align:right;">8</td><td>三千</td><td>three thousand</td><td>tlitt elef</td></tr><tr><td style="text-align:right;">9</td><td>一万</td><td>ten thousand</td><td>għaxra elf</td></tr><tr><td style="text-align:right;">10</td><td>十万</td><td>one hundred thousand</td><td>mija elf</td></tr></tbody></table><p>大数示例按常见计数形式组合。<code>mija</code> 用于单独报数或组合数值；<code>mitt</code> 是在名词前的限定形式。</p><h2 id="_8-参考核对" tabindex="-1">8. 参考核对 <a class="header-anchor" href="#_8-参考核对" aria-label="Permalink to &quot;8. 参考核对&quot;">​</a></h2><ul><li><a href="https://www.omniglot.com/language/numbers/maltese.htm" target="_blank" rel="noreferrer">Omniglot：Maltese numbers</a></li><li><a href="https://en.wiktionary.org/wiki/mija#Maltese" target="_blank" rel="noreferrer">Wiktionary：mija</a></li><li><a href="https://en.wiktionary.org/wiki/ewwel#Maltese" target="_blank" rel="noreferrer">Wiktionary：ewwel</a></li></ul>',25),l=[a];function n(o,h,s,g,x,c){return d(),e("div",null,l)}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
